<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Form W-2G</title>
<style>
  body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 10px;
    color: black;
    margin: 20px;
    display: flex;
    justify-content: center;
  }
  .form-container {
    width: 850px;
    display: flex;
    flex-direction: column;
  }
  .header {
    text-align: center;
    margin-bottom: 4px;
    font-size: 14px;
  }
  .checkbox {
    display: inline-block;
    width: 14px;
    height: 14px;
    border: 1px solid black;
    vertical-align: middle;
    margin-right: 4px;
  }
  .main-grid {
    display: grid;
    grid-template-columns: 4.5fr 2fr 2fr 1.5fr;
    background-color: black;
    gap: 1px;
    border: 1px solid black;
  }
  .cell {
    background-color: white;
    padding: 4px;
    box-sizing: border-box;
    position: relative;
  }
  .cell:not(.nested-grid), .nested-cell {
    min-height: 36px;
  }
  .cell.flex-col {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }
  .nested-grid {
    padding: 0;
    display: grid;
    background-color: black;
    gap: 1px;
  }
  .nested-cell {
    background-color: white;
    padding: 4px;
    box-sizing: border-box;
  }
  .label {
    font-size: 9px;
    line-height: 1.1;
  }
  .box-number {
    font-weight: bold;
    font-size: 10px;
    margin-right: 3px;
  }
  .thick-border {
    box-shadow: inset 0 0 0 2px black;
  }
  .grey-box {
    background-color: #d3d3d3;
  }
</style>
</head>
<body>

<div class="form-container">
  <div class="header">
    <span class="checkbox"></span>
    <span style="vertical-align: middle;">CORRECTED (if checked)</span>
  </div>

  <div class="main-grid">
    <!-- Row 1 -->
    <div class="cell"><div class="label">PAYER'S name</div></div>
    <div class="cell flex-col">
      <div class="label"><span class="box-number">1</span> Reportable winnings</div>
      <div>$</div>
    </div>
    <div class="cell">
      <div class="label"><span class="box-number">2</span> Date won</div>
    </div>
    <div class="cell" style="grid-row: span 4; text-align: center; padding: 8px 4px; display: flex; flex-direction: column; justify-content: space-between;">
      <div style="font-size: 8px;">OMB No. 1545-0238</div>
      <div style="font-size: 18px; font-weight: bold;">Form W-2G</div>
      <div style="font-size: 13px; font-weight: bold; line-height: 1.1;">Certain<br>Gambling<br>Winnings</div>
      <div style="font-size: 8px;">(Rev. January 2026)</div>
      <div style="font-size: 9px;">For calendar year<br>20&nbsp;&nbsp;&nbsp;&nbsp;</div>
    </div>

    <!-- Row 2 -->
    <div class="cell nested-grid" style="grid-template-columns: 7fr 3fr;">
      <div class="nested-cell"><div class="label">Street address</div></div>
      <div class="nested-cell"><div class="label">Room or suite no.</div></div>
    </div>
    <div class="cell">
      <div class="label"><span class="box-number">3</span> Type of wager</div>
    </div>
    <div class="cell flex-col thick-border">
      <div class="label"><span class="box-number">4</span> Federal income tax withheld</div>
      <div>$</div>
    </div>

    <!-- Row 3 -->
    <div class="cell"><div class="label">City or town</div></div>
    <div class="cell">
      <div class="label"><span class="box-number">5</span> Transaction</div>
    </div>
    <div class="cell">
      <div class="label"><span class="box-number">6</span> Race</div>
    </div>

    <!-- Row 4 -->
    <div class="cell nested-grid" style="grid-template-columns: 3.5fr 2.5fr 4fr;">
      <div class="nested-cell"><div class="label">State or province</div></div>
      <div class="nested-cell"><div class="label">Country</div></div>
      <div class="nested-cell"><div class="label">ZIP or foreign postal code</div></div>
    </div>
    <div class="cell flex-col">
      <div class="label"><span class="box-number">7</span> Winnings from identical wagers</div>
      <div>$</div>
    </div>
    <div class="cell">
      <div class="label"><span class="box-number">8</span> Cashier</div>
    </div>

    <!-- Row 5 -->
    <div class="cell nested-grid" style="grid-template-columns: 1fr 1fr;">
      <div class="nested-cell"><div class="label">PAYER'S TIN</div></div>
      <div class="nested-cell"><div class="label">PAYER'S telephone no.</div></div>
    </div>
    <div class="cell">
      <div class="label"><span class="box-number">9</span> WINNER'S TIN</div>
    </div>
    <div class="cell">
      <div class="label"><span class="box-number">10</span> Window</div>
    </div>
    <div class="cell" style="grid-row: span 5; padding: 8px; font-size: 9.5px; line-height: 1.25; text-align: right; display: flex; align-items: center; justify-content: flex-end;">
      <div>
        This is important<br>tax information and<br>is being furnished<br>to the IRS. If you<br>are required to file a<br>return, a negligence<br>penalty or other<br>sanction may be<br>imposed on you<br>if this income is<br>taxable and the<br>IRS determines<br>that it has not<br>been reported.
      </div>
    </div>

    <!-- Row 6 -->
    <div class="cell"><div class="label">WINNER'S name</div></div>
    <div class="cell">
      <div class="label"><span class="box-number">11</span> First identification no.</div>
    </div>
    <div class="cell">
      <div class="label"><span class="box-number">12</span> Second identification no.</div>
    </div>

    <!-- Row 7 -->
    <div class="cell nested-grid" style="grid-template-columns: 8fr 2fr;">
      <div class="nested-cell"><div class="label">Street address</div></div>
      <div class="nested-cell"><div class="label">Apt. no.</div></div>
    </div>
    <div class="cell">
      <div class="label"><span class="box-number">13</span> State/Payer's state<br>identification no.</div>
    </div>
    <div class="cell flex-col">
      <div class="label"><span class="box-number">14</span> State winnings</div>
      <div>$</div>
    </div>

    <!-- Row 8 -->
    <div class="cell"><div class="label">City or town</div></div>
    <div class="cell flex-col" style="grid-row: span 2;">
      <div class="label"><span class="box-number">15</span> State income tax<br>withheld</div>
      <div>$</div>
    </div>
    <div class="cell flex-col" style="grid-row: span 2;">
      <div class="label"><span class="box-number">16</span> Local winnings</div>
      <div>$</div>
    </div>

    <!-- Row 9 -->
    <div class="cell nested-grid" style="grid-template-columns: 3.5fr 2.5fr 4fr;">
      <div class="nested-cell"><div class="label">State or province</div></div>
      <div class="nested-cell"><div class="label">Country</div></div>
      <div class="nested-cell"><div class="label">ZIP or foreign postal code</div></div>
    </div>

    <!-- Row 10 -->
    <div class="cell grey-box"></div>
    <div class="cell flex-col">
      <div class="label"><span class="box-number">17</span> Local income tax<br>withheld</div>
      <div>$</div>
    </div>
    <div class="cell">
      <div class="label"><span class="box-number">18</span> Name of locality</div>
    </div>
    <div class="cell" style="padding: 8px; text-align: right; display: flex; flex-direction: column; justify-content: flex-end;">
      <div style="font-size: 14px; font-weight: bold; margin-bottom: 4px;">Copy C</div>
      <div style="font-size: 10px; font-weight: bold;">For Winner's Records</div>
    </div>
  </div>

  <div style="border: 1px solid black; border-top: none; padding: 4px 6px; font-size: 8.5px; line-height: 1.2;">
    Under penalties of perjury, I declare that, to the best of my knowledge and belief, the name, address, and taxpayer identification number that I have furnished correctly identify me as the recipient of this payment and any payments from identical wagers, and that no other person is entitled to any part of these payments.
  </div>

  <div style="display: flex; justify-content: space-between; padding: 8px 6px 4px 6px; font-size: 11px; font-weight: bold;">
    <div>Signature:</div>
    <div style="width: 35%;">Date:</div>
  </div>

  <div style="border-top: 1px solid black; display: flex; justify-content: space-between; padding: 4px 0; font-size: 9px;">
    <div>Form <b>W-2G</b> (Rev. 1-2026)</div>
    <div>www.irs.gov/FormW2G</div>
    <div>Department of the Treasury - Internal Revenue Service</div>
  </div>

</div>

</body>
</html>
```
